// Checks resources with arguments on the lookup app (rt-test/lookup,
// generated by plan2cpp): each asks its source with the values of its
// arguments, asks again when a slot, a derive or another resource's answer
// that they read changes, and not when they keep their values; a refresh asks
// again with the same arguments. While the source gives no answer, a resource
// shows its placeholder row's answer, its declared value, or its type's zero.
// Prints each failure; exit 0 when all pass.
#include <cstdio>
#include <string>
#include <vector>

#include "exact_rt.h"
#include "ext_lookup.h"

namespace app {
extern const rt::App kApp;
}

namespace {

class Clock : public rt::Board {
 public:
  int64_t micros() const override { return 0; }
};

// Answers "word:id", with next `id + step`, and records each request; gives
// no answer for the word "quiet".
class Lookup : public ext::LookupExtension {
 public:
  double step = 10;
  std::vector<std::string> asks;

  bool lookup(double id, const std::string& word, ext::LookupExtension::Lookup& out) override {
    const std::string request = word + ":" + rt::number_text(id);
    asks.push_back(request);
    out.label = request;
    out.next = id + step;
    return word != "quiet";
  }
  // The requests of `entry` and `after`: words starting "w", and "after".
  std::string lookups() const {
    std::string out;
    for (const std::string& a : asks) {
      if (a[0] == 'w' || a.compare(0, 6, "after:") == 0) out += (out.empty() ? "" : " ") + a;
    }
    return out;
  }
};

int failures = 0;

void expect(bool ok, const std::string& what) {
  if (!ok) {
    ++failures;
    std::printf("FAIL %s\n", what.c_str());
  }
}

bool contains(const std::string& text, const std::string& part) { return text.find(part) != std::string::npos; }

// The text of the node with `test_id`, from the agent's node list.
bool shows(rt::Runtime& runtime, const std::string& test_id, const std::string& text) {
  return contains(runtime.agent("{\"op\":\"nodes\"}"), "\"testId\":\"" + test_id + "\",\"text\":\"" + text + "\"");
}

void check_bound() {
  Clock board;
  Lookup lookup;
  rt::Runtime runtime(app::kApp, board, {&lookup});
  expect(runtime.boot(), "boot");
  expect(lookup.lookups() == "wa:1 after:11", "boot asks " + lookup.lookups());
  expect(shows(runtime, "entry", "wa:1"), "entry at boot");
  expect(shows(runtime, "after", "after:11"), "after at boot");

  lookup.asks.clear();
  expect(runtime.tap("step"), "tap step");
  runtime.tick();
  expect(lookup.lookups() == "wa:2 after:12", "a slot argument asks again, and so does the resource reading its answer: " + lookup.lookups());
  expect(shows(runtime, "after", "after:12"), "after follows entry");

  lookup.asks.clear();
  expect(runtime.tap("rename"), "tap rename");
  runtime.tick();
  expect(lookup.lookups() == "wb:2", "a derive argument asks again; an unchanged answer field asks nothing more: " + lookup.lookups());
  expect(shows(runtime, "entry", "wb:2"), "entry follows the derive");

  lookup.asks.clear();
  expect(runtime.tap("rename"), "tap rename again");
  runtime.tick();
  expect(lookup.asks.empty(), "arguments that keep their values ask nothing: " + lookup.lookups());

  lookup.asks.clear();
  lookup.step = 20;
  runtime.refresh(0);
  expect(lookup.lookups() == "wb:2 after:22", "a refresh asks with the same arguments: " + lookup.lookups());
  expect(shows(runtime, "after", "after:22"), "after follows the refreshed entry");
}

void check_placeholders() {
  Clock board;
  Lookup lookup;
  rt::Runtime runtime(app::kApp, board, {&lookup});
  expect(runtime.boot(), "placeholders: boot");
  expect(shows(runtime, "held", "held:0"), "no answer shows the placeholder row's answer");
  expect(shows(runtime, "preset", "preset"), "no answer shows the declared value");
  expect(shows(runtime, "plain", ""), "no answer shows the type's zero");
  expect(contains(runtime.agent("{\"op\":\"state\"}"), "\"plain\":{\"label\":\"\",\"next\":0}"),
         "the zero is a record of zeros: " + runtime.agent("{\"op\":\"state\"}"));
  expect(runtime.tap("speak"), "tap speak");
  runtime.tick();
  expect(shows(runtime, "held", "spoken:1"), "an answer replaces the placeholder row's");
  expect(shows(runtime, "preset", "spoken:1"), "an answer replaces the declared value");
  expect(shows(runtime, "plain", "spoken:1"), "an answer replaces the zero");
}

void check_unbound() {
  Clock board;
  rt::Runtime runtime(app::kApp, board, {});
  expect(runtime.boot(), "unbound: boot");
  expect(shows(runtime, "entry", ""), "unbound: entry is its zero");
  expect(runtime.tap("step"), "unbound: tap step");
  runtime.tick();
  expect(shows(runtime, "after", ""), "unbound: after is its zero");
  expect(shows(runtime, "held", ""), "unbound: a placeholder row with no answer shows none");
  expect(shows(runtime, "preset", "preset"), "unbound: preset is its declared value");
}

}  // namespace

int main() {
  check_bound();
  check_placeholders();
  check_unbound();
  std::printf("lookup_check: %s\n", failures ? "failures" : "all checks pass");
  return failures ? 1 : 0;
}
